/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: homePage, setupPages, placement, expectFits, expectOrder, beginChangedOrder, visualOrderPage
 *   Constants: revision, referenceId, headers, initialNames, reorderPath
 * Tests
 *   - Page items preserve order, warnings and nullable metadata while reading only the selected page
 *   - any page revision change invalidates a captured visibility confirmation and Escape restores focus
 *   - unconfirmed visibility names its original target and retries the same body; a conflict offers refresh
 *   - Page order adjustment keeps keyboard focus, boundary moves and unchanged drafts local until cancelled
 *   - native dragging previews displaced rows before release and saves only the complete confirmed order
 *   - a stale order confirmation can cancel or refresh into a new draft after any page change
 *   - unknown order results retain the approved order while refresh and exact retry preserve newer server changes
 *   - a definite order conflict offers cancellation or refreshed adjustment without resending the old order
 *   - the source07 six-placement specimen renders approved dragging, complete confirmation and recovery states
 * @end-catalog */

import { expect, test, type Page } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
import { capabilities, session, viewer } from '../src/features/admin/adminFixtures.testSupport';
import type { AdminPage } from '../src/features/admin/catalogApi';

const revision = `cr_${'a'.repeat(43)}`;
const referenceId = '333333333333333333333333';
const headers = { 'X-Finitude-Account-Viewer': viewer, 'Cache-Control': 'no-store' };

/** Distinct synthetic placements exercise metadata and warnings without touching catalog records. */
function homePage(): AdminPage {
  return { slug: 'home', title: 'Home', revision, items: [
    { itemId: '111111111111111111111111', itemType: 'carousel', referenceId, order: 0, visibility: 'public', name: 'Chiikawa', sourceMode: 'manual', referenceStatus: 'ready' },
    { itemId: '222222222222222222222222', itemType: 'grid', referenceId, order: 1, visibility: 'hidden', name: 'Carefully selected recordings for long evenings and quiet mornings', sourceMode: 'manual', referenceStatus: 'ready' },
    { itemId: '444444444444444444444444', itemType: 'list', referenceId, order: 2, visibility: 'public', name: 'Recently Played', sourceMode: 'dynamic', referenceStatus: 'ready' },
    { itemId: '555555555555555555555555', itemType: 'carousel', referenceId, order: 3, visibility: 'public', name: null, sourceMode: null, referenceStatus: 'missing' },
    { itemId: '666666666666666666666666', itemType: 'list', referenceId, order: 4, visibility: 'hidden', name: 'Legacy collection', sourceMode: null, referenceStatus: 'unsupported' }
  ] };
}

/** Page reads and mutations retain the real owner header, revision fence and original retry identity. */
async function setupPages(page: Page, locale: 'en-US' | 'zh-Hans' = 'en-US', initial: AdminPage = homePage()) {
  let home = structuredClone(initial);
  let library: AdminPage = { slug: 'library', title: 'Library', revision, items: [
    { ...home.items[0], itemId: '777777777777777777777777', name: 'Recently Played', sourceMode: 'dynamic' },
    { ...home.items[1], itemId: '888888888888888888888888', itemType: 'carousel', name: 'Recently Saved', sourceMode: 'dynamic' }
  ] };
  const reads: string[] = [], writes: Array<{ path: string; body: Record<string, unknown> }> = [];
  const appliedOrders = new Map<string, Record<string, unknown>>();
  let outcome: 'confirmed' | 'unknown' | 'conflict' = 'confirmed', revisionSequence = 1;
  let nextWriteBarrier: Promise<void> | null = null;
  const nextRevision = () => `cr_${String.fromCharCode(97 + revisionSequence++).repeat(43)}`;
  await page.addInitScript(({ preference }) => window.localStorage.setItem('finitude.localization.preference.v1', preference), { preference: locale });
  await page.route('**/auth/browser/session', route => route.fulfill({ json: session }));
  await page.route('**/api/listener/v1/capabilities', route => route.fulfill({ json: { playlists: false } }));
  await page.route('**/api/listener/v1/personalization-capabilities', route => route.fulfill({ json: { contractVersion: 1, deterministicDiscovery: false, artistFollows: false } }));
  await page.route('**/api/listener/v1/home', route => route.fulfill({ json: { title: 'Synthetic Home', sections: [] }, headers }));
  await page.route('**/content/me/playlists?limit=50', route => route.fulfill({ json: { items: [], nextCursor: null }, headers }));
  await page.route('**/api/admin/v1/**', async route => {
    const request = route.request(), pathname = new URL(request.url()).pathname;
    expect(request.headers()['x-finitude-account-viewer']).toBe(viewer);
    if (pathname === '/api/admin/v1/capabilities') return route.fulfill({ json: { ...capabilities, catalog: { editing: true, visibility: true } }, headers });
    if (request.method() === 'GET' && /^\/api\/admin\/v1\/pages\/(home|library)$/.test(pathname)) {
      const slug = pathname.split('/').at(-1)!; reads.push(slug);
      return route.fulfill({ json: { page: slug === 'home' ? home : library }, headers });
    }
    if (request.method() === 'POST' && /^\/api\/admin\/v1\/pages\/(home|library)\/reorder$/.test(pathname)) {
      const body = request.postDataJSON() as { itemIds: string[]; expectedRevision: string; operationId: string };
      writes.push({ path: pathname, body });
      const barrier = nextWriteBarrier; nextWriteBarrier = null; await barrier;
      const slug = pathname.split('/').at(-2), snapshot = slug === 'home' ? home : library;
      expect(Object.keys(body).sort()).toEqual(['expectedRevision', 'itemIds', 'operationId']);
      expect(body.itemIds.slice().sort()).toEqual(snapshot.items.map(item => item.itemId).sort());
      if (appliedOrders.has(body.operationId)) {
        expect(body).toEqual(appliedOrders.get(body.operationId));
        return route.fulfill({ json: { page: snapshot, receipt: { operationId: body.operationId } }, headers });
      }
      if (outcome === 'conflict') return route.fulfill({ status: 409, json: { code: 'ADMIN_PAGE_CONFLICT', message: 'Synthetic page conflict' }, headers });
      expect(body.expectedRevision).toBe(snapshot.revision);
      const byId = new Map(snapshot.items.map(item => [item.itemId, item]));
      const reordered = { ...snapshot, revision: nextRevision(), items: body.itemIds.map((id, order) => ({ ...byId.get(id)!, order })) };
      if (slug === 'home') home = reordered; else library = reordered;
      appliedOrders.set(body.operationId, structuredClone(body));
      // A lost receipt does not roll back a confirmed server mutation; an exact retry cannot overwrite later edits.
      if (outcome === 'unknown') { outcome = 'confirmed'; return route.fulfill({ status: 503, json: { message: 'Synthetic lost reorder receipt' }, headers }); }
      return route.fulfill({ json: { page: reordered, receipt: { operationId: body.operationId } }, headers });
    }
    if (request.method() === 'PATCH' && pathname.startsWith('/api/admin/v1/pages/home/items/')) {
      const body = request.postDataJSON(); writes.push({ path: pathname, body });
      const barrier = nextWriteBarrier; nextWriteBarrier = null; await barrier;
      if (outcome === 'unknown') { outcome = 'confirmed'; return route.fulfill({ status: 503, json: { message: 'Synthetic unconfirmed outcome' }, headers }); }
      if (outcome === 'conflict') return route.fulfill({ status: 409, json: { code: 'ADMIN_PAGE_CONFLICT', message: 'Synthetic page conflict' }, headers });
      home = { ...home, revision: nextRevision(), items: home.items.map(item => item.itemId === pathname.split('/').at(-1) ? { ...item, visibility: body.visibility } : item) };
      return route.fulfill({ json: { page: home, receipt: { operationId: body.operationId } }, headers });
    }
    throw new Error(`Unexpected synthetic administrator request: ${request.method()} ${pathname}`);
  });
  await page.goto('/finitude/admin/pages');
  await page.getByRole('button', { name: locale === 'zh-Hans' ? '切换到管理员视角' : 'Switch to Admin view', exact: true }).click();
  await expect(page.getByRole('heading', { name: '1 · Chiikawa', exact: true })).toBeVisible();
  return {
    reads, writes,
    changeElsewhere: () => { home = { ...home, revision: nextRevision(), items: home.items.map((item, index) => index === 1 ? { ...item, name: 'Changed elsewhere' } : item) }; },
    updateHome: (update: (snapshot: AdminPage) => AdminPage) => { home = { ...update(structuredClone(home)), revision: nextRevision() }; },
    currentHome: () => structuredClone(home),
    appliedOrders: () => appliedOrders.size,
    holdNextWrite: () => { let release!: () => void; nextWriteBarrier = new Promise<void>(resolve => { release = resolve; }); return release; },
    respondWith: (next: typeof outcome) => { outcome = next; }
  };
}

/** A real list item contains its name and independent mutation/disclosure controls. */
const placement = (page: Page, name: string) => page.getByRole('listitem').filter({ has: page.getByRole('heading', { name, exact: true }) });

/** Reflow must preserve every action and avoid horizontal document overflow. */
async function expectFits(page: Page) {
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth && document.body.scrollWidth <= innerWidth)).toBe(true);
  for (const control of await page.getByRole('button').all()) {
    if (!(await control.isVisible())) continue;
    const bounds = await control.boundingBox();
    expect(bounds!.x).toBeGreaterThanOrEqual(0);
    expect(bounds!.x + bounds!.width).toBeLessThanOrEqual(await page.evaluate(() => innerWidth));
  }
}

test('Page items preserve order, warnings and nullable metadata while reading only the selected page', async ({ page, context }, info) => {
  await page.setViewportSize({ width: 1440, height: 1100 });
  const server = await setupPages(page);
  await expect(page.getByRole('listitem').getByRole('heading')).toHaveText(['Chiikawa', 'Carefully selected recordings for long evenings and quiet mornings', 'Recently Played', 'Unnamed placement', 'Legacy collection']);
  await expect(page.getByText('Referenced content is missing', { exact: true })).toBeVisible();
  await expect(page.getByText('Unsupported reference', { exact: true })).toBeVisible();
  expect(server.reads).toEqual(['home']);
  await expect(page.getByRole('button', { name: 'Home', exact: true })).toHaveText(/Home\s*5/);
  await expect(page.getByRole('button', { name: 'Library', exact: true })).toHaveText(/Library\s*—/);
  const unnamed = placement(page, '4 · Unnamed placement');
  await expect(unnamed.getByText('Carousel', { exact: true })).toBeVisible();
  await expect(unnamed.getByText('Manual', { exact: true })).toHaveCount(0);
  await expect(unnamed.getByText('Dynamic', { exact: true })).toHaveCount(0);
  await expect(unnamed).not.toContainText('·');
  const first = placement(page, '1 · Chiikawa');
  await expect(first.getByText(referenceId, { exact: true })).not.toBeVisible();
  await first.getByRole('button', { name: 'Details', exact: true }).click();
  await expect(first.getByRole('button', { name: 'Hide details', exact: true })).toBeVisible();
  await expect(first.getByText(referenceId, { exact: true })).toBeVisible();
  await context.grantPermissions(['clipboard-read', 'clipboard-write']);
  await first.getByRole('button', { name: 'Copy reference ID', exact: true }).click();
  await expect.poll(() => page.evaluate(() => navigator.clipboard.readText())).toBe(referenceId);
  expect(server.writes).toHaveLength(0);
  await page.screenshot({ path: info.outputPath('page-items-mixed-en.png'), fullPage: true });
  await page.setViewportSize({ width: 1280, height: 900 });
  await expectFits(page);
  await page.screenshot({ path: info.outputPath('page-items-details-en-1280.png'), fullPage: true });
  await page.setViewportSize({ width: 1440, height: 1100 });
  await page.getByRole('button', { name: 'Library', exact: true }).click();
  await expect(page.getByRole('heading', { name: '1 · Recently Played', exact: true })).toBeVisible();
  expect(server.reads).toEqual(['home', 'library']);
  await expect(page.getByRole('button', { name: 'Library', exact: true })).toHaveText(/Library\s*2/);
  await expect(page.getByRole('button', { name: 'Home', exact: true })).toHaveText(/Home\s*—/);
  await page.screenshot({ path: info.outputPath('page-items-library-en.png'), fullPage: true });
  expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
});

test('any page revision change invalidates a captured visibility confirmation and Escape restores focus', async ({ page }, info) => {
  const server = await setupPages(page);
  const action = placement(page, '1 · Chiikawa').getByRole('button', { name: 'Hide this placement', exact: true });
  await action.click();
  const dialog = page.getByRole('dialog', { name: 'Change visibility?' });
  await expect(dialog.getByRole('button', { name: 'Cancel', exact: true })).toBeFocused();
  await expect(dialog.getByText('Public → Hidden', { exact: true })).toBeVisible();
  await expect(dialog).toHaveAttribute('aria-describedby', /.+/);
  server.changeElsewhere();
  // React Query refreshes stale reads when a visible page regains focus; the open approval keeps its captured revision.
  await page.evaluate(() => window.dispatchEvent(new Event('visibilitychange')));
  await expect(dialog.getByText('This page has changed. Close this dialog, refresh and review it before confirming again.', { exact: true })).toBeVisible();
  await expect(dialog.getByRole('button', { name: 'Hide this placement', exact: true })).toBeDisabled();
  await page.screenshot({ path: info.outputPath('page-items-confirmation-stale-en.png'), fullPage: true });
  await page.keyboard.press('Escape');
  await expect(action).toBeFocused();
  expect(server.writes).toHaveLength(0);
  expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
});

test('unconfirmed visibility names its original target and retries the same body; a conflict offers refresh', async ({ page }, info) => {
  const server = await setupPages(page);
  server.respondWith('unknown');
  const first = placement(page, '1 · Chiikawa');
  await first.getByRole('button', { name: 'Hide this placement', exact: true }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'Hide this placement', exact: true }).click();
  const alert = page.getByRole('alert');
  await expect(alert).toContainText('Chiikawa');
  await expect(alert).toContainText('Hide this placement');
  await expect(page.getByRole('button', { name: 'Retry original operation', exact: true })).toBeVisible();
  await expect(first.getByRole('button', { name: 'Hide this placement', exact: true })).toBeDisabled();
  await expect(page.getByRole('button', { name: 'Adjust order', exact: true })).toBeDisabled();
  await page.screenshot({ path: info.outputPath('page-items-unknown-operation-en.png'), fullPage: true });
  await page.getByRole('button', { name: 'Retry original operation', exact: true }).click();
  await expect(first.getByRole('button', { name: 'Make this placement public', exact: true })).toBeVisible();
  expect(server.writes).toHaveLength(2); expect(server.writes[1]).toEqual(server.writes[0]);
  server.respondWith('conflict');
  await first.getByRole('button', { name: 'Make this placement public', exact: true }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'Make this placement public', exact: true }).click();
  await expect(alert).toContainText('This page was updated by another operation. Refresh and review it again.');
  await expect(alert.getByRole('button', { name: 'Refresh status', exact: true })).toBeVisible();
  await expect(page.getByRole('button', { name: 'Refresh status', exact: true })).toHaveCount(1);
  await expect(page.getByRole('button', { name: 'Retry original operation', exact: true })).toHaveCount(0);
  expect(server.writes).toHaveLength(3);
  await page.screenshot({ path: info.outputPath('page-items-conflict-en.png'), fullPage: true });
});

