  await page.evaluate(() => window.dispatchEvent(new Event('visibilitychange')));
  await expect(dialog.getByRole('button', { name: '刷新并重新调整', exact: true })).toBeVisible();
  await page.screenshot({ path: info.outputPath('synthetic-order-reference-stale-zh-Hans.png'), fullPage: true });
  await dialog.getByRole('button', { name: '取消调整', exact: true }).click();
  await page.getByRole('button', { name: '调整顺序', exact: true }).click();
  const freshHandle = draft.getByRole('button', { name: '调整 Aniplex 的顺序', exact: true });
  await freshHandle.focus(); await freshHandle.press('ArrowUp');
  await page.getByRole('button', { name: '保存顺序', exact: true }).click();
  server.respondWith('unknown');
  await dialog.getByRole('button', { name: '确认保存顺序', exact: true }).click();
  const notice = page.getByRole('alert');
  await expect(notice).toContainText('首页：排序保存结果尚未确认');
  await notice.getByText('查看原操作的顺序', { exact: true }).click();
